    .meta { color: #586574; font-size: .9rem; } [role="alert"] { color: #a21b1b; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form">
    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorBox = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    async function refresh() {
      try {
        const response = await fetch('/api/jobs');
        const data = await response.json();
        list.innerHTML = data.jobs.map(job => `<li data-testid="job-item" data-job-id="${esc(job.id)}"><strong>${esc(job.input)}</strong><div class="meta"><span data-testid="job-status">${esc(job.status)}</span> · <span data-testid="job-progress">${job.progress.completed}/${job.progress.total}</span> · ${job.attempts} attempt(s)</div><div data-testid="job-result">${job.result ? esc(job.result.output) : job.error ? esc(job.error) : ''}</div></li>`).join('');
      } catch (_) { /* next poll retries */ }
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorBox.textContent = '';
      const payload = { input: form.elements.input.value, steps: Number(form.elements.steps.value), failAttempts: Number(form.elements.failAttempts.value) };
      try {
        const response = await fetch('/api/jobs', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
        const data = await response.json();
        if (!response.ok) {
          const details = data.error?.fields?.map(f => `${f.field}: ${f.message}`).join(' ') || data.error?.message || 'Submission rejected.';
          errorBox.textContent = details;
        } else { form.elements.input.value = ''; await refresh(); }
      } catch (_) { errorBox.textContent = 'Unable to submit job.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
</body>
</html>
